-- Holiday commoners wear the costume of the holiday that is on (Four, 2026-11-28: a Thunder Bluff Tauren
-- Commoner in his green and white Christmas outfit during Pilgrim's Bounty).
--
-- The commoners in the capital cities (Human 18927, Dwarf 19148, Blood Elf 19169, Draenei 19171, Gnome 19172,
-- Night Elf 19173, Orc 19175, Tauren 19176, Troll 19177, Forsaken 19178, Goblin 20102) come out for the holidays
-- (game_event_creature, see 2026_11_18_46_holiday_spawn_events.sql). Their costumes were stuck on whatever
-- holiday the spawn was sniffed in:
--   - Thunder Bluff Tauren 138126 in the Christmas outfit (33465) all year; Blood Elf 138132 and Gnomes
--     138118/138106 likewise (33415, 33448, 33445).
--   - Lunar Festival outfits all year: Blood Elf 138151 (33413), Goblins 138214/138200/138193/138221 (34848),
--     138134 (34851).
--   - Day of the Dead (65529) on 93882/93889, Pirates' Day (50531) on 93829/93836/93857, Midsummer (65526) on
--     138077/138152/138082/130871/138222 and on the Human and Troll templates.
-- And the SmartAI that dresses them for the current holiday was missing; only the conditions for it were there.
--
-- From TrinityCore's 8.3.7 world DB:
--   smart_scripts ids 13-19 (on spawn) and their action lists <entry>00-<entry>10: a random male/female costume
--   for Winter Veil (2), Hallow's End (12), Lunar Festival (7); Brewfest Reveler (24); Day of the Dead (51) and
--   Pirates' Day (50) morphs; the Midsummer Celebrant Costume (1). Each id N runs only while condition group N+1
--   (conditions source 22, event active) holds; those conditions are rewritten from TDB too (unchanged for 9
--   entries, new for Human and Blood Elf). No costume for the other holidays (Noblegarden, Pilgrim's Bounty):
--   commoners wear their everyday clothes then.
--   The holiday appearance auras above are removed; the plain per-gender appearance auras (33411, 33426,
--   33432, 33473, 33476, 34847, 34850) and the Gossip NPC Periodic auras 33207-33209 stay. Templates 18927 and
--   19177 get Default 65523 like the others instead of Midsummer 65526.
-- The commoners' own SmartAI rows 0-1 (gossip) are untouched.

DELETE FROM `smart_scripts` WHERE `source_type`=0 AND `entryorguid` IN (18927,19148,19169,19171,19172,19173,19175,19176,19177,19178,20102) AND `id` BETWEEN 13 AND 19;
DELETE FROM `smart_scripts` WHERE `source_type`=9 AND FLOOR(`entryorguid`/100) IN (18927,19148,19169,19171,19172,19173,19175,19176,19177,19178,20102);

DELETE FROM `conditions` WHERE `SourceTypeOrReferenceId`=22 AND `SourceEntry` IN (18927,19148,19169,19171,19172,19173,19175,19176,19177,19178,20102) AND `SourceGroup` BETWEEN 14 AND 20;

-- Holiday appearance auras stuck on spawns and templates
UPDATE `creature_addon` SET `auras`='' WHERE `guid` IN (138126,138132,138118,138106,138151,138214,138200,138193,138221,138134,93882,93889,93829,93836,93857);
UPDATE `creature_addon` SET `auras`='33432' WHERE `guid`=138077;
UPDATE `creature_addon` SET `auras`='33411' WHERE `guid`=138152;
UPDATE `creature_addon` SET `auras`='33426' WHERE `guid`=138082;
UPDATE `creature_addon` SET `auras`='34850' WHERE `guid`=130871;
UPDATE `creature_addon` SET `auras`='34847' WHERE `guid`=138222;
UPDATE `creature_template_addon` SET `auras`='65523 33209 33207 33208' WHERE `entry` IN (18927,19177);
